    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    marker = max((value for value in counts if value != background), key=lambda v: counts[v])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    top = min(r for r, c in points)
    bottom = max(r for r, c in points)
    left = min(c for r, c in points)
    right = max(c for r, c in points)
    out = [row[:] for row in grid]

    # Fill only the two horizontal rails of the frame.
    for c in range(left, right + 1):
        if grid[top][c] == background:
            out[top][c] = 2
        if grid[bottom][c] == background:
            out[bottom][c] = 2

    # Vertical runs are determined independently by a streak of at least
    # three markers in that column (not merely the bounding-box sides).
    for c in range(left, right + 1):
        rows = [r for r in range(top, bottom + 1) if grid[r][c] == marker]
        if len(rows) >= 3:
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2

    # Interior horizontal runs are likewise supported by at least three
    # source markers; pairs alone can be separate objects.
    for r in range(top + 1, bottom):
        cols = [c for c in range(left + 1, right) if grid[r][c] == marker]
        if len(cols) >= 3:
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out
